  'hochzeitstag.title': 'Ons hart', 'hochzeitstag.sub': 'Trek met je vinger het hart in de boom na – de lantaarns gaan aan en aan het eind staan jullie initialen in de schors.', 'hochzeitstag.hint': 'Volg de lichtende stip rond het hart!', 'hochzeitstag.msg': 'Fijne trouwdag!', 'hochzeitstag.msgN': 'Fijne trouwdag, {name}!', 'hochzeitstag.years': '{n} jaar – en elke dag meer.', 'hochzeitstag.score': 'Hart gekerfd in {s} s', 'hochzeitstag.best': 'Snelste hart: {s} s',
