  'taufe.title': 'Wolken wegvegen', 'taufe.sub': 'Vijf wolken bedekken de hemel boven de kapel. Schuif ze zacht opzij – dan schijnt de zon en luiden de klokken.', 'taufe.hint': 'Veeg de wolken weg!', 'taufe.msg': 'Gefeliciteerd met je doop!', 'taufe.msgN': 'Gefeliciteerd met je doop, {name}!', 'taufe.line': 'Gods zegen op al je wegen.',
  'verlobung.title': 'Waar is de ring?', 'verlobung.sub': 'De ring verstopt zich in een van de drie doosjes – en dan wordt er geschud! Vind je hem? Drie rondes, steeds sneller.', 'verlobung.hint': 'Welk doosje? Tik erop!', 'verlobung.merk': 'Let goed op de ring …', 'verlobung.msg': 'Gefeliciteerd met jullie verloving!', 'verlobung.msgN': 'Gefeliciteerd met jullie verloving, {name}!', 'verlobung.line': 'Op een ja voor altijd!', 'verlobung.ja': 'Gevonden!', 'verlobung.leer': 'Leeg!', 'verlobung.score': '{n} van 3 gevonden', 'verlobung.runde': 'Ronde {n}/3',
  'halloween.title': 'Pompoen-echo', 'halloween.sub': 'De pompoenen lichten één voor één op – onthoud de volgorde en tik ze na! Elke ronde wordt de reeks langer.', 'halloween.hint': 'Maak je klaar – kijk goed!', 'halloween.schau': 'Kijk …', 'halloween.du': 'Nu jij!', 'halloween.buh': 'Boe!', 'halloween.msg': 'Fijne Halloween!', 'halloween.msgN': 'Fijne Halloween, {name}!', 'halloween.line': 'Snoep of je leven!', 'halloween.score': 'Reeks: {n}', 'halloween.best': 'Record: {n}',
