  'schwester.msg': 'Wszystkiego najlepszego, siostrzyczko!', 'schwester.msgN': 'Wszystkiego najlepszego, {name}!', 'schwester.title': 'Balonowe party', 'schwester.sub': 'Balony są przywiązane do prezentu. Dotknij jednego – sznurek pęka i balon leci w górę. Szybko dotknij znowu, a pęknie w konfetti!', 'schwester.hint': 'Dotknij balonów!', 'schwester.peng': 'Bum!', 'schwester.weg': 'Uciekł!', 'schwester.line': 'Jak dobrze, że jesteś!', 'schwester.score': '{n} z 5 pękniętych',
  'ehemann.title': 'Prosto w serce', 'ehemann.sub': 'Pięć lotek, jedna tarcza – a w środku serce. Przesuń lotkę w górę na tarczę. Serce to 50 punktów!', 'ehemann.hint': 'Przesuń lotkę na tarczę!', 'ehemann.herz': 'Prosto w serce!', 'ehemann.wand': 'Ściana!', 'ehemann.msg': 'Wszystkiego najlepszego, kochanie!', 'ehemann.msgN': 'Wszystkiego najlepszego, {name}!', 'ehemann.line': 'Każdego dnia trafiasz prosto w moje serce.', 'ehemann.score': '{n} punktów', 'ehemann.best': 'Rekord: {n}',
  'ehefrau.title': 'Gwiazdy w słoiku', 'ehefrau.sub': 'Przyniosę ci gwiazdy z nieba! Przeciągnij pięć gwiazd do słoika – tam dalej świecą.', 'ehefrau.hint': 'Przeciągnij gwiazdy do słoika!', 'ehefrau.msg': 'Wszystkiego najlepszego, kochanie!', 'ehefrau.msgN': 'Wszystkiego najlepszego, {name}!', 'ehefrau.line': 'Dla ciebie zdejmę wszystkie gwiazdy z nieba.', 'ehefrau.score': 'Zebrane w {s} s', 'ehefrau.best': 'Rekord: {s} s',
